-- Read-only verification after 03-blog-apply.sql. Every row should say PASS.
select 'blog RLS enabled' as check_name,case when (select relrowsecurity from pg_class where oid='public.wuus_blog_posts'::regclass) then 'PASS' else 'FAIL' end as result
union all select 'public blog SELECT enabled',case when has_table_privilege('anon','public.wuus_blog_posts','SELECT') and has_table_privilege('authenticated','public.wuus_blog_posts','SELECT') then 'PASS' else 'FAIL' end
union all select 'no public blog writes',case when not exists(select 1 from unnest(array['anon','authenticated']) r cross join unnest(array['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p where has_table_privilege(r,'public.wuus_blog_posts',p)) then 'PASS' else 'FAIL' end
union all select 'one public SELECT policy',case when (select count(*)=1 and bool_and(cmd='SELECT' and roles @> array['anon','authenticated']::name[]) from pg_policies where schemaname='public' and tablename='wuus_blog_posts') then 'PASS' else 'FAIL' end
union all select 'private QA proof inaccessible',case when not has_schema_privilege('anon','wuus_private','USAGE') and not has_schema_privilege('authenticated','wuus_private','USAGE') and not has_table_privilege('anon','wuus_private.blog_release_receipts','SELECT') and not has_table_privilege('authenticated','wuus_private.blog_release_receipts','SELECT') then 'PASS' else 'FAIL' end
union all select 'publisher RPC service only',case when has_function_privilege('service_role','public.publish_wuus_blog(jsonb)','EXECUTE') and not has_function_privilege('anon','public.publish_wuus_blog(jsonb)','EXECUTE') and not has_function_privilege('authenticated','public.publish_wuus_blog(jsonb)','EXECUTE') then 'PASS' else 'FAIL' end
union all select 'receipt RPC service only',case when has_function_privilege('service_role','public.wuus_blog_receipt(uuid)','EXECUTE') and not has_function_privilege('anon','public.wuus_blog_receipt(uuid)','EXECUTE') and not has_function_privilege('authenticated','public.wuus_blog_receipt(uuid)','EXECUTE') then 'PASS' else 'FAIL' end;
